import math

class Rational:
    def __init__(self, numer, denom):
        if denom == 0:
            raise ZeroDivisionError("Denominator cannot be zero")

        # Handle zero numerator first: 0/anything is 0/1
        if numer == 0:
            self.numer = 0
            self.denom = 1
            return

        # Calculate GCD for reduction.
        # math.gcd typically expects non-negative arguments, or its behavior for negative inputs
        # results in gcd(a,b) == gcd(abs(a), abs(b)), so using abs() is explicit and safe.
        common_divisor = math.gcd(abs(numer), abs(denom))

        # Reduce to lowest terms
        self.numer = numer // common_divisor
        self.denom = denom // common_divisor

        # Ensure standard form: denominator is always positive
        if self.denom < 0:
            self.numer *= -1
            self.denom *= -1

    def __eq__(self, other):
        # Assuming `other` is also a Rational instance for direct comparison.
        # The `__init__` method ensures all Rational objects are reduced to lowest terms
        # and in standard form (positive denominator), so a direct comparison of
        # numerators and denominators is sufficient.
        if not isinstance(other, Rational):
            return NotImplemented
        return self.numer == other.numer and self.denom == other.denom

    def __repr__(self):
        return f'{self.numer}/{self.denom}'

    def __add__(self, other):
        # r₁ + r₂ = (a₁ * b₂ + a₂ * b₁) / (b₁ * b₂)
        new_numer = self.numer * other.denom + other.numer * self.denom
        new_denom = self.denom * other.denom
        return Rational(new_numer, new_denom)

    def __sub__(self, other):
        # r₁ - r₂ = (a₁ * b₂ - a₂ * b₁) / (b₁ * b₂)
        new_numer = self.numer * other.denom - other.numer * self.denom
        new_denom = self.denom * other.denom
        return Rational(new_numer, new_denom)

    def __mul__(self, other):
        # r₁ * r₂ = (a₁ * a₂) / (b₁ * b₂)
        new_numer = self.numer * other.numer
        new_denom = self.denom * other.denom
        return Rational(new_numer, new_denom)

    def __truediv__(self, other):
        # r₁ / r₂ = (a₁ * b₂) / (a₂ * b₁) if a₂ is not zero
        if other.numer == 0:
            raise ZeroDivisionError("Cannot divide by a rational number with zero numerator")
        new_numer = self.numer * other.denom
        new_denom = self.denom * other.numer
        return Rational(new_numer, new_denom)

    def __abs__(self):
        # |r| = |a|/|b|. Since self.denom is always positive, this simplifies to |self.numer| / self.denom.
        return Rational(abs(self.numer), self.denom)

    def __pow__(self, power):
        if isinstance(power, int):
            # Exponentiation to a non-negative integer power `n`: r^n = (a^n)/(b^n)
            if power >= 0:
                return Rational(self.numer ** power, self.denom ** power)
            # Exponentiation to a negative integer power `n`: r^n = (b^m)/(a^m), where m = |n|
            else:
                if self.numer == 0:
                    raise ZeroDivisionError("Cannot raise zero to a negative power")
                m = abs(power)
                return Rational(self.denom ** m, self.numer ** m)
        elif isinstance(power, float):
            # Exponentiation to a real (floating-point) number `x`: (a^x)/(b^x), which is a real number.
            # Convert numerator and denominator to float for the power operation, then divide.
            return (float(self.numer) ** power) / (float(self.denom) ** power)
        else:
            # For other types of power, indicate that the operation is not implemented.
            return NotImplemented

    def __rpow__(self, base):
        # Exponentiation of a real number `x` to a rational number `r = a/b`:
        # x^(a/b) = root(x^a, b), which is equivalent to `base**(self.numer / self.denom)`.
        # The result should be a real number. We use `math.pow` for its defined behavior
        # regarding negative bases and non-integer exponents (e.g., it raises ValueError
        # for even roots of negative numbers, which do not result in a real number).
        try:
            return math.pow(base, self.numer / self.denom)
